using System.ComponentModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

const string modelId = "gpt-4o-mini-2024-07-18";

// --- Build the IChatClient via MEAI abstraction ---
IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

// --- Define tools ---
var tools = new AITool[]
{
    AIFunctionFactory.Create(WebSearch),
    AIFunctionFactory.Create(SaveNote),
    AIFunctionFactory.Create(GetNotes),
};

// --- Create the agent with instructions and tools ---
var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research assistant. When given a topic:
        1. Use the web_search tool multiple times with different queries to gather information.
        2. Use the save_note tool to record each key finding as you go.
        3. Use the get_notes tool to review all your findings.
        4. After researching, provide a comprehensive summary with key points and sources.
        Be thorough — search at least 3 different queries before summarizing.
        """,
    tools: tools);

// --- Get the research topic ---
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

// --- Run the agent ---
var session = await agent.CreateSessionAsync();
var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 4096,
});

var response = await agent.RunAsync($"Research this topic: {topic}", session, runOptions);

Console.WriteLine("═══════════════════════════════════════");
Console.WriteLine("  RESEARCH SUMMARY");
Console.WriteLine("═══════════════════════════════════════");
Console.WriteLine(response.Text);
Console.WriteLine("═══════════════════════════════════════");

// --- Tool implementations ---

var notebook = new List<string>();

[Description("Search the web for information on a query. Returns search result snippets.")]
static string WebSearch([Description("The search query")] string query)
{
    // Simulated web search results for demonstration.
    // In production, wire this to Bing Search API, Google Custom Search, etc.
    Console.WriteLine($"  🔍 Searching: \"{query}\"");

    var results = new Dictionary<string, string[]>(StringComparer.OrdinalIgnoreCase)
    {
        ["quantum computing"] =
        [
            "[Source: MIT Tech Review] Quantum computers use qubits that can exist in superposition, enabling parallel computation. Google's Willow chip (2024) demonstrated quantum error correction below threshold.",
            "[Source: Nature] IBM's 1,121-qubit Condor processor launched in 2023. Quantum advantage demonstrated for specific optimization and simulation tasks.",
            "[Source: IEEE Spectrum] Key challenges remain: decoherence, error rates, and scaling. Current machines require near-absolute-zero cooling.",
        ],
        ["artificial intelligence"] =
        [
            "[Source: Stanford HAI] AI adoption in enterprise grew 72% since 2020. Large language models dominate NLP tasks. Concerns around bias, safety, and regulation intensify.",
            "[Source: DeepMind] AlphaFold solved protein structure prediction. AI now assists drug discovery, climate modeling, and materials science.",
            "[Source: NIST] The EU AI Act (2024) establishes risk-based regulation. US executive orders focus on safety testing and transparency requirements.",
        ],
        ["climate change"] =
        [
            "[Source: IPCC AR6] Global temperatures have risen ~1.1°C since pre-industrial times. Limiting to 1.5°C requires 43% emissions reduction by 2030.",
            "[Source: NASA] Arctic sea ice declining at 13% per decade. 2023 was the hottest year on record. Ocean heat content at all-time highs.",
            "[Source: IEA] Renewable energy capacity grew 50% in 2023, led by solar. EVs reached 18% of global car sales. Green hydrogen projects scaling up.",
        ],
    };

    // Find a matching topic or return generic results
    var key = results.Keys.FirstOrDefault(k => query.Contains(k, StringComparison.OrdinalIgnoreCase));
    if (key is not null)
    {
        return string.Join("\n\n", results[key]);
    }

    return $"""
        [Source: Wikipedia] {query} is an active area of research with significant recent developments.
        [Source: Reuters] Industry analysts project continued growth and investment in {query} through 2026.
        [Source: arXiv] Recent papers explore novel approaches to {query}, with promising preliminary results.
        """;
}

[Description("Save a research note to the notebook for later reference.")]
string SaveNote(
    [Description("Title or label for the note")] string title,
    [Description("Content of the note")] string content)
{
    var note = $"## {title}\n{content}";
    notebook.Add(note);
    Console.WriteLine($"  📝 Note saved: \"{title}\"");
    return $"Note saved: {title} ({notebook.Count} total notes)";
}

[Description("Retrieve all saved research notes.")]
string GetNotes()
{
    if (notebook.Count == 0)
    {
        return "No notes saved yet.";
    }

    Console.WriteLine($"  📋 Retrieving {notebook.Count} notes");
    return string.Join("\n\n---\n\n", notebook);
}

